-- Rolls the seeded view counts into the daily table the merchant analytics
-- screen reads, so the dashboard is not empty before any real traffic.
insert into deal_analytics_daily (deal_id, day, impressions, views, search_appearances)
select id, current_date, view_count * 3, view_count, search_count from deals
on conflict (deal_id, day) do update set
  impressions = excluded.impressions, views = excluded.views,
  search_appearances = excluded.search_appearances;

